from orders.pricing import apply_discount


def test_apply_discount_subtracts_percentage_off_price():
    assert apply_discount(100.00, 0.25) == 75.00


def test_apply_discount_zero_discount_leaves_price_unchanged():
    assert apply_discount(50.00, 0.0) == 50.00


def test_apply_discount_full_discount_is_free():
    assert apply_discount(50.00, 1.0) == 0.0


def test_apply_discount_out_of_range_raises():
    import pytest

    with pytest.raises(ValueError):
        apply_discount(100.00, 1.5)

